const SIGN_COPY = [
  ['Neon', 'Line 03 · after dark', '#31e7c9'],
  ['Metro', 'Ride the night', '#ffcc4d'],
  ['Run', 'No brakes · no regrets', '#ff5d63'],
  ['Downtown', 'Two stops to glory', '#8a6bff'],
